    # Read all sheets without header to get raw coordinates easier
    all_sheets = pd.read_excel('nasa_budget_incomplete.xlsx', sheet_name=None, header=None)

    for sheet_name, df in all_sheets.items():
        print(f"--- Sheet: {sheet_name} ---")
        # Find cells with "???"
        for r_idx, row in df.iterrows():
            for c_idx, value in enumerate(row):
                if str(value) == "???":
                    print(f"Missing at Row {r_idx}, Col {c_idx} ({chr(65+c_idx)}{r_idx+1})")
                    # Print context
                    print(f"  Row context: {row.tolist()}")

        if sheet_name == "Budget by Directorate":
            print("  Column Headers likely at row 1 (0-indexed):")
